function extractEntities(text) {
  const t = " " + text.toLowerCase() + " ";  // pad for boundary matching
  const found = new Set();
  for (const [entity, terms] of Object.entries(KNOWN_ENTITIES)) {
    if (terms.some(term => {
      // Multi-word terms: plain includes is fine (e.g. "federal reserve")
      if (term.includes(" ")) return t.includes(term);
      // Single-word terms: require word boundary to prevent
      // "gold" matching "Goldman", "dollar" matching "Dollar General"
      const re = new RegExp(`\\b${term}\\b`);
      return re.test(t);
    })) found.add(entity);
  }
  return [...found];
}

function detectDirection(text) {
  const t = " " + text.toLowerCase() + " ";
  // Use word boundaries for single-word terms to prevent false positives
  // like "slides" (PowerPoint) → down, "gains" (non-market) → up
  const matchesAny = (terms) => terms.some(w => {
    if (w.includes(" ")) return t.includes(w);  // multi-word: plain match
    return new RegExp(`\\b${w}\\b`).test(t);  // single-word: boundary match
  });
  if (matchesAny(DIR_UP))   return "up";
  if (matchesAny(DIR_DOWN)) return "down";
  if (matchesAny(DIR_HOLD)) return "hold";
  return "neutral";
}

/* ── Multi-layer scoring function ──────────────────────────────── */
function scoreImportance(text, rules) {
  // rules = priorityRules from state; falls back to defaults if not passed
  const R = rules || DEFAULT_PRIORITY_RULES;
  const t = text.toLowerCase();
  let score = R.baseScore;

  // Layer 1: Catastrophic / systemic events
  // Multi-word terms are safe; single words need financial context nearby
  const CATASTROPHIC_MULTI = ["war declared","sanctions imposed","debt default","sovereign default","market crash","market collapse","bank collapse","currency collapse"];
  const CATASTROPHIC_CONTEXT = ["emergency","bankrupt","invasion","nuclear"];
  const FINANCIAL_CONTEXT = ["market","economy","bank","currency","stock","bond","fund","debt","credit","yield","trade","fiscal","monetary"];
  if (CATASTROPHIC_MULTI.some(w=>t.includes(w))) return R.catastrophicFloor;
  if (CATASTROPHIC_CONTEXT.some(w=>t.includes(w)) && FINANCIAL_CONTEXT.some(w=>t.includes(w))) return R.catastrophicFloor;

  // Layer 2: Tier-1 data releases
  if (DATA_RELEASES.tier1.some(w=>t.includes(w)))    score = Math.max(score, R.tier1DataFloor);
  if (DATA_RELEASES.au_tier1.some(w=>t.includes(w))) score = Math.max(score, R.auTier1Floor);

  // Layer 3: CB decisions vs speeches
  if (CB_ACTIONS.some(w=>t.includes(w)))             score = Math.max(score, R.cbDecisionFloor);
  else if (CB_SPEECHES.some(w=>t.includes(w)))        score = Math.max(score, R.cbSpeechFloor);

  // Layer 4: Tier-2 data
  if (DATA_RELEASES.tier2.some(w=>t.includes(w)))    score = Math.max(score, R.tier2DataFloor);
  if (DATA_RELEASES.au_tier2.some(w=>t.includes(w))) score = Math.max(score, R.auTier2Floor);

  // Layer 5: Earnings
  if (TIER1_EARNINGS.some(w=>t.includes(w)) && (t.includes("earn")||t.includes("result")||t.includes("revenue")||t.includes("profit")||t.includes("quarter")))
    score = Math.max(score, R.tier1EarningsFloor);
  else if (TIER1_EARNINGS.some(w=>t.includes(w)))
    score = Math.max(score, R.tier1EarningsAnyFloor);
  if (TIER2_EARNINGS.some(w=>t.includes(w)) && t.includes("earn"))
    score = Math.max(score, R.tier2EarningsFloor);

  // Layer 6: Geopolitics
  if (["tariff","trade war","sanction","conflict","tension","military"].some(w=>t.includes(w))) score = Math.max(score, R.geopoliticsFloor);

  // Layer 7: Market movers
  if (["cpi","inflation","gdp","recession","fomc","rate cut","rate hike","rba","fed"].some(w=>t.includes(w))) score = Math.max(score, R.marketMoversFloor);
  if (["oil","gold","crude","bitcoin","yield","treasury","unemployment"].some(w=>t.includes(w))) score = Math.max(score, R.fxCommoditiesFloor + 1);
  if (["dollar","euro","yen","pound","aud","equities","stocks","nasdaq"].some(w=>t.includes(w))) score = Math.max(score, R.fxCommoditiesFloor);

  // Layer 8: AU relevance bonus
  if (score >= R.auBonusThreshold && ["australia","asx","rba","aud","iron ore","china gdp"].some(w=>t.includes(w)))
    score = Math.min(10, score + R.auRelevanceBonus);

  // Layer 9: User custom rules — checked last, can override any built-in score
  if (R.customRules && R.customRules.length > 0) {
    for (const rule of R.customRules) {
      if (!rule.enabled || !rule.keywords) continue;
      const kwList = rule.keywords.toLowerCase().split(",").map(k=>k.trim()).filter(Boolean);
      const mode   = rule.mode || "any"; // "any" | "all"
      const match  = mode === "all"
        ? kwList.every(kw => t.includes(kw))
        : kwList.some(kw => t.includes(kw));
      if (match) {
        if (rule.action === "floor")  score = Math.max(score, rule.score || 7);
        if (rule.action === "set")    score = rule.score || 7;
        if (rule.action === "boost")  score = Math.min(10, score + (rule.score || 1));
        if (rule.action === "cap")    score = Math.min(score, rule.score || 5);
        if (rule.action === "exclude") { score = 0; break; } // score 0 = will be filtered
      }
    }
  }

  // Score 0 = excluded by custom rule — don't clamp it
  if (score <= 0) return 0;
  return Math.max(1, Math.min(10, score));
}

