function extractAccentWords(headline) {
  const h = headline.toLowerCase();
  for (const [kw, display] of KW_ACCENT) {
    if (h.includes(kw)) return display;
  }
  const words = headline.split(" ").filter(w => w.length > 3 && /^[A-Z]/.test(w));
  return words.slice(0,2).join(" ") || headline.split(" ")[0];
}

/* ─── SOURCE HEALTH + SIMILARITY UTILS ─────────────────────────── */
function getAgeHours(fetchedAt) {
  return fetchedAt ? (Date.now() - fetchedAt) / 3600000 : 0;
}
function getAgeLabel(fetchedAt) {
  const h = getAgeHours(fetchedAt);
  if (h < 1) return Math.round(h * 60) + "m ago";
  if (h < 24) return Math.round(h) + "h ago";
  return Math.round(h / 24) + "d ago";
}
function getStaleStatus(fetchedAt) {
  const h = getAgeHours(fetchedAt);
  if (h < 6)  return "fresh";
  if (h < 24) return "recent";
  if (h < 48) return "stale";
  return "old";
}

