function detectTopic(headline, entities) {
  const t = headline.toLowerCase();
  let bestTopic = null, bestScore = 0;

  for (const seed of TOPIC_SEEDS) {
    const kwMatches = seed.keywords.filter(kw => t.includes(kw)).length;

    let entityBonus = 0;
    if (seed.entities.length === 0) {
      // Keywords-only seed (Nvidia, Apple, Bitcoin): no entity bonus.
      // Must have ≥1 keyword match to score at all.
      if (kwMatches === 0) continue;
    } else if (seed.entities.length === 1) {
      // Single-entity seed: entity must be present for any score.
      if (!entities.includes(seed.entities[0])) continue;
      entityBonus = 2;
    } else {
      // Multi-entity seed (AUD/USD, US Jobs, Trade War etc):
      // ALL entities must be present (AND logic).
      const allMatch = seed.entities.every(e => entities.includes(e));
      if (!allMatch) continue;
      entityBonus = 3; // higher confidence when all entities match
    }

    const score = entityBonus + kwMatches;
    // Minimum meaningful score: entity-only seeds need ≥1 kw, others need ≥3 total
    const minScore = seed.entities.length === 0 ? 1 : 3;
    if (score >= minScore && score > bestScore) {
      bestScore = score;
      bestTopic = seed.topic;
    }
  }
  return bestTopic;
}

// Entity-aware similarity signature
function headlineSig(headline) {
  const tokens = headline.toLowerCase()
    .replace(/[^a-z0-9 ]/g," ")
    .split(/\s+/)
    .filter(w => w.length > 2 && !STOP_WORDS.has(w));
  // Prefer entity tokens + numeric tokens for the signature
  const entities = tokens.filter(w => {
    return Object.values(KNOWN_ENTITIES).some(terms => terms.some(t => t === w || t.startsWith(w)));
  });
  const numbers  = tokens.filter(w => /\d/.test(w));
  const keyTerms = [...new Set([...entities, ...numbers, ...tokens])].slice(0, 7);
  return keyTerms.sort().join(" ");
}

// Full topic-based clustering — returns array of cluster objects
function buildTopicClusters(headlines) {
  const topicMap = {}; // topic -> [headlines]
  const noTopic  = []; // unclusterable
  headlines.forEach(h => {
    const entities = extractEntities(h.headline + " " + (h.summary||""));
    const topic    = detectTopic(h.headline, entities);
    const dir      = detectDirection(h.headline);
    const enriched = { ...h, entities, direction:dir, topic: topic || "General" };
    if (topic) {
      if (!topicMap[topic]) topicMap[topic] = [];
      topicMap[topic].push(enriched);
    } else {
      noTopic.push(enriched);
    }
  });
  // Build cluster objects sorted by best importance in cluster
  const clusters = Object.entries(topicMap).map(([topic, items]) => {
    const best = items.reduce((a,b) => (b.importance>a.importance?b:a));
    return {
      topic,
      items: items.sort((a,b)=>b.importance-a.importance),
      importance: best.importance,
      sourceCount: new Set(items.map(i=>i.source)).size,
      directions: [...new Set(items.map(i=>i.direction).filter(d=>d!=="neutral"))],
      leadHeadline: best,
    };
  }).sort((a,b)=>b.importance-a.importance);
  // Unclustered go in as single-item clusters
  noTopic.forEach(h => {
    clusters.push({ topic:h.topic, items:[h], importance:h.importance, sourceCount:1, directions:[h.direction], leadHeadline:h });
  });
  return clusters;
}

function parseRssXml(xmlText, sourceName, rules) {
  const parser = new DOMParser();
  const doc = parser.parseFromString(xmlText, "text/xml");
  // Support both RSS 2.0 (<item>) and Atom (<entry>) feeds
  const isAtom = doc.querySelector("feed") !== null;
  const items = isAtom
    ? [...doc.querySelectorAll("entry")]
    : [...doc.querySelectorAll("item")];
  const fetchedAt = Date.now();
  return items.slice(0, 8).map((item, i) => {
    const headline = item.querySelector("title")?.textContent?.trim() || "";
    // Atom uses <summary> or <content>, RSS uses <description>
    const rawDesc  = isAtom
      ? (item.querySelector("summary")?.textContent || item.querySelector("content")?.textContent || "")
      : (item.querySelector("description")?.textContent || "");
    const summary  = rawDesc
      .replace(/<[^>]+>/g,"")           // strip HTML tags
      .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(n))  // decode &#8217; etc
      .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h,16)))
      .replace(/&quot;/g,'"').replace(/&apos;/g,"'")
      .replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">")
      .replace(/&nbsp;/g," ").replace(/&mdash;/g,"—").replace(/&ndash;/g,"–")
      .replace(/&rsquo;/g,"'").replace(/&lsquo;/g,"'").replace(/&rdquo;/g,'"').replace(/&ldquo;/g,'"')
      .replace(/\s{2,}/g," ").trim().slice(0,200);
    // Atom uses <published> or <updated>; RSS uses <pubDate>
    const pubDate  = isAtom
      ? (item.querySelector("published")?.textContent || item.querySelector("updated")?.textContent || "")
      : (item.querySelector("pubDate")?.textContent || "");
    // Atom uses <link href="..."> (attribute), RSS uses <link> text content
    const rawLink  = isAtom
      ? (item.querySelector("link[href]")?.getAttribute("href") || item.querySelector("link")?.textContent?.trim() || "")
      : (item.querySelector("link")?.textContent?.trim() || "");
    const link     = /^https?:\/\/.{10,}/.test(rawLink) ? rawLink : "";
    const importance = scoreImportance(headline + " " + summary, rules);
    const category   = detectCategory(headline + " " + summary);
    const accentWords = extractAccentWords(headline);
    let eventDate = "", pubMs = 0;
    try {
      const d = new Date(pubDate);
      if (!isNaN(d)) { eventDate = d.toLocaleDateString("en-AU",{day:"numeric",month:"short",weekday:"short"}); pubMs = d.getTime(); }
    } catch(_){}
    // Boost importance if published very recently (< 3h)
    const ageH = pubMs ? (fetchedAt - pubMs) / 3600000 : 48;
    const boostedImportance = ageH < 3 ? Math.min(10, importance + 1) : ageH > 36 ? Math.max(1, importance - 2) : importance;
    const entities  = extractEntities(headline + " " + summary);
    const direction  = detectDirection(headline);
    const topic      = detectTopic(headline, entities);
    return { id:`${sourceName}-${i}`, headline, summary, source:sourceName, category, importance:boostedImportance, accentWords, eventDate, link, fetchedAt, pubMs, sourceCount:1, entities, direction, topic: topic||"General" };
  }).filter(h => h.headline.length > 10);
}

const CAT_COLORS = {
  "Forex":          "#3B82F6",
  "Equities":       "#10B981",
  "Commodities":    "#F59E0B",
  "Central Banks":  "#004E5A",
  "Geopolitics":    "#EF4444",
  "Economic Data":  "#8B5CF6",
  "Crypto":         "#EC4899",
};

function getWeekLabel() {
  const d   = new Date();
  const mon = new Date(d);
  const day = mon.getDay();
  mon.setDate(mon.getDate() - day + (day === 0 ? -6 : 1));
  return `WEEK AHEAD | WEEK OF ${mon.toLocaleDateString("en-AU",{day:"numeric",month:"short",year:"numeric"}).toUpperCase()}`;
}

/* ─── INJECT FONTS ───────────────────────────────────────────────── */
function useFont() {
  useEffect(() => {
    // Load Outfit (Gilroy alternative) + Plus Jakarta Sans
    ["Outfit","Plus Jakarta Sans"].forEach(family => {
      const id = "gf-" + family.replace(/\s/g,"-").toLowerCase();
      if (document.getElementById(id)) return;
      const l = document.createElement("link");
      l.id = id; l.rel = "stylesheet";
      l.href = `https://fonts.googleapis.com/css2?family=${encodeURIComponent(family)}:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;0,900&display=swap`;
      document.head.appendChild(l);
    });
  }, []);
}

