/* ─── HEADLINE CARD ──────────────────────────────────────────────── */
function HeadlineCard({ h, selected, dragging, dragOver, onToggle, onDragStart, onDragOver, onDrop, onDragEnd, onPreview, onExpand, expandedIds }) {
  const cat   = h.category || "Other";
  const cc    = CAT_COLORS[cat] || B.orange;
  const score = h.importance || 5;
  const scoreCol = score >= 8 ? B.orange : score >= 5 ? B.teal : "#374151";
  const hDir    = h.direction||"neutral";
  const dirIcon = hDir==="up"?"▲":hDir==="down"?"▼":hDir==="hold"?"━":"";
  const dirCol  = hDir==="up"?"#34d399":hDir==="down"?"#F87171":"#9CA3AF";
  const isExpanded = !!onExpand && (expandedIds||new Set()).has(h.id);

  return (
    <div
      draggable
      onDragStart={e => onDragStart(e, h.id)}
      onDragOver={e => { e.preventDefault(); e.stopPropagation(); onDragOver(h.id); }}
      onDrop={e => { e.preventDefault(); e.stopPropagation(); onDrop(h.id); }}
      onDragEnd={()=>onDragEnd&&onDragEnd()}
      onClick={() => onToggle(h.id)}
      style={{
        background: dragOver ? "rgba(227,87,40,0.14)" : selected ? "rgba(227,87,40,0.07)" : "rgba(255,255,255,0.03)",
        border: `1px solid ${dragOver ? B.orange : selected ? `${B.orange}55` : B.border}`,
        borderRadius: 10,
        padding: "11px 13px",
        cursor: "grab",
        opacity: dragging ? 0.35 : 1,
        transition: "all 0.15s",
        userSelect: "none",
        marginBottom: 7,
      }}
    >
      <div style={{ display:"flex", gap:10, alignItems:"flex-start" }}>
        {/* Score badge */}
        <div style={{ width:28, height:28, borderRadius:6, background:scoreCol, display:"flex", alignItems:"center", justifyContent:"center", fontSize:11, fontWeight:800, color:"white", flexShrink:0 }}>
          {score}
        </div>

        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ fontSize:12, fontWeight:600, color:"white", lineHeight:1.45, marginBottom:5 }}>{h.headline}</div>
          <div style={{ display:"flex", gap:5, flexWrap:"wrap", alignItems:"center" }}>
            <span style={{ fontSize:10, color:B.muted }}>{h.source}</span>
            <span style={{ fontSize:9, fontWeight:700, color:cc, background:`${cc}1A`, padding:"2px 7px", borderRadius:4 }}>{cat}</span>
            {h.topic && h.topic!=="General" && <span style={{ fontSize:9, color:"#C4B5FD", background:"rgba(196,181,253,0.12)", padding:"2px 6px", borderRadius:4 }}>{h.topic}</span>}
            {dirIcon && <span style={{ fontSize:9, fontWeight:700, color:dirCol }}>{dirIcon}</span>}
            {h.eventDate && <span style={{ fontSize:9, color:"#9CA3AF", fontStyle:"italic" }}>{h.eventDate}</span>}
            {h.sourceCount > 1 && <span style={{ fontSize:9, fontWeight:700, color:"#a78bfa", background:"rgba(167,139,250,0.15)", padding:"2px 6px", borderRadius:4 }}>📡 {h.sourceCount} sources</span>}
            {h.fetchedAt && <span style={{ fontSize:9, color:getStaleStatus(h.fetchedAt)==="fresh"?"#34d399":getStaleStatus(h.fetchedAt)==="stale"?"#FBBF24":"#9CA3AF" }}>{getAgeLabel(h.fetchedAt)}</span>}
            {h.clusterSize > 1 && onExpand && (
              <button onClick={e=>{ e.stopPropagation(); onExpand(h.id); }}
                style={{ fontSize:8, fontWeight:700, color:isExpanded?"#F59E0B":"#6B7280", background:isExpanded?"rgba(245,158,11,0.12)":"rgba(255,255,255,0.05)", border:"none", borderRadius:3, padding:"1px 5px", cursor:"pointer", fontFamily:"inherit" }}>
                {isExpanded?"▾ collapse":"+"+h.clusterSize+" stories"}
              </button>
            )}
          </div>
          {/* Expanded cluster view */}
          {isExpanded && h.clusterItems && h.clusterItems.length > 1 && (
            <div style={{ marginTop:8, paddingTop:8, borderTop:`1px dashed ${B.border}` }}>
              {h.clusterItems.slice(1).map((item,ci)=>{
                const itemDir = item.direction==="up"?"▲":item.direction==="down"?"▼":item.direction==="hold"?"━":"";
                const itemDirCol = item.direction==="up"?"#34d399":item.direction==="down"?"#F87171":"#9CA3AF";
                return (
                  <div key={ci} style={{ display:"flex", alignItems:"flex-start", gap:7, marginBottom:5, paddingLeft:4, borderLeft:`2px solid ${B.border}` }}>
                    <div style={{ flexShrink:0, marginTop:2 }}>
                      {itemDir && <span style={{ fontSize:9, fontWeight:800, color:itemDirCol }}>{itemDir}</span>}
                    </div>
                    <div style={{ flex:1 }}>
                      <div style={{ fontSize:11, color:"#D1D5DB", lineHeight:1.5 }}>{item.headline}</div>
                      <div style={{ fontSize:9, color:B.muted, marginTop:2 }}>{item.source} · {getAgeLabel(item.fetchedAt)}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        <div style={{ display:"flex", flexDirection:"column", gap:4, flexShrink:0, alignItems:"center" }}>
          <div style={{ fontSize:15, color: selected ? B.orange : "#374151", fontWeight:700 }}>
            {selected ? "✓" : "+"}
          </div>
          <button onClick={e=>{ e.stopPropagation(); onPreview&&onPreview(h); }}
            title="Preview full headline"
            style={{ background:"none", border:`1px solid ${B.border}`, borderRadius:4, color:B.muted, fontSize:9, cursor:"pointer", padding:"1px 5px", fontFamily:"inherit", lineHeight:1.4 }}>
            👁
          </button>
        </div>
      </div></div>
  );
}

