/* ─── ASSET LIBRARY PANEL ──────────────────────────────────────────────── */
const ASSET_TYPES = ["All","Logo","Background","Icon","Photo","Brand"];

function AssetLibraryPanel({ onUseAsset, selectedEl }) {
  const [assets,      setAssets]      = useState([]);
  const [search,      setSearch]      = useState("");
  const [filterType,  setFilterType]  = useState("All");
  const [filterFolder,setFilterFolder]= useState("All");
  const [recentIds,   setRecentIds]   = useState([]);
  const [showAdd,     setShowAdd]     = useState(false);
  const [tagInput,    setTagInput]    = useState("");
  const [pendingAsset,setPendingAsset]= useState(null); // {dataUrl,name,type,folder,tags}

  const folders = ["All", ...new Set(assets.map(a=>a.folder).filter(Boolean))];

  function uploadFile() {
    const inp = document.createElement("input");
    inp.type="file"; inp.accept="image/*"; inp.multiple=true;
    inp.onchange = e => {
      const files = [...e.target.files];
      files.forEach(f=>{
        const r=new FileReader();
        r.onload=ev=>setPendingAsset({dataUrl:ev.target.result,name:f.name.replace(/\.[^.]+$/,""),type:"Logo",folder:"",tags:[]});
        r.readAsDataURL(f);
      });
    };
    inp.click();
  }

  function saveAsset() {
    if (!pendingAsset) return;
    const newA = { ...pendingAsset, id:"ast-"+Date.now(), tags: tagInput.split(",").map(t=>t.trim()).filter(Boolean) };
    setAssets(p=>[newA,...p]);
    setRecentIds(r=>[newA.id,...r].slice(0,10));
    setPendingAsset(null); setTagInput(""); setShowAdd(false);
  }

  function useAsset(asset) {
    setRecentIds(r=>[asset.id,...r.filter(x=>x!==asset.id)].slice(0,10));
    onUseAsset(asset);
  }

  const filtered = assets.filter(a=>{
    const matchType   = filterType==="All"   || a.type===filterType;
    const matchFolder = filterFolder==="All" || a.folder===filterFolder;
    const matchSearch = !search || a.name.toLowerCase().includes(search.toLowerCase()) ||
                        (a.tags||[]).some(t=>t.toLowerCase().includes(search.toLowerCase()));
    return matchType && matchFolder && matchSearch;
  });

  const recent = recentIds.map(id=>assets.find(a=>a.id===id)).filter(Boolean);

  return (
    <div style={{ padding:14, overflowY:"auto", height:"100%" }}>
      <div style={{ fontSize:10, fontWeight:700, color:B.orange, letterSpacing:"0.08em", textTransform:"uppercase", marginBottom:12, paddingBottom:10, borderBottom:`1px solid ${B.border}` }}>
        📁 Asset Library
      </div>

      {/* Search */}
      <input value={search} onChange={e=>setSearch(e.target.value)}
        placeholder="Search by name or tag…"
        style={{ ...propInput, marginBottom:8 }}/>

      {/* Type filter */}
      <div style={{ display:"flex", gap:4, flexWrap:"wrap", marginBottom:8 }}>
        {ASSET_TYPES.map(t=>(
          <button key={t} onClick={()=>setFilterType(t)}
            style={{ fontSize:9.5, fontWeight:600, padding:"3px 9px", borderRadius:100, cursor:"pointer", fontFamily:"inherit",
              background:filterType===t?B.orange:"rgba(255,255,255,0.06)",
              border:`1px solid ${filterType===t?B.orange:B.border}`, color:"white" }}>{t}</button>
        ))}
      </div>

      {/* Folder filter */}
      {folders.length>1 && (
        <select value={filterFolder} onChange={e=>setFilterFolder(e.target.value)}
          style={{ ...propInput, marginBottom:10, background:"#152032", color:"#E5E7EB" }}>
          {folders.map(f=><option key={f} value={f}>{f}</option>)}
        </select>
      )}

      {/* Upload button */}
      <button onClick={uploadFile}
        style={{ ...eBtn, width:"100%", justifyContent:"center", marginBottom:12, border:`1.5px dashed ${B.border}` }}>
        ↑ Upload Asset
      </button>

      {/* Pending asset form */}
      {pendingAsset && (
        <div style={{ background:`${B.orange}0E`, border:`1px solid ${B.orange}33`, borderRadius:10, padding:12, marginBottom:12 }}>
          <img src={pendingAsset.dataUrl} style={{ width:"100%", height:70, objectFit:"cover", borderRadius:7, marginBottom:8 }}/>
          <input value={pendingAsset.name} onChange={e=>setPendingAsset(p=>({...p,name:e.target.value}))}
            placeholder="Asset name" style={{ ...propInput, marginBottom:6 }}/>
          <div style={{ display:"flex", gap:6, marginBottom:6 }}>
            <select value={pendingAsset.type} onChange={e=>setPendingAsset(p=>({...p,type:e.target.value}))}
              style={{ ...propInput, background:"#152032", color:"#E5E7EB" }}>
              {ASSET_TYPES.filter(t=>t!=="All").map(t=><option key={t}>{t}</option>)}
            </select>
            <input value={pendingAsset.folder} onChange={e=>setPendingAsset(p=>({...p,folder:e.target.value}))}
              placeholder="Folder (opt)" style={{ ...propInput }}/>
          </div>
          <input value={tagInput} onChange={e=>setTagInput(e.target.value)}
            placeholder="Tags: aud, rba, logo (comma sep)"
            style={{ ...propInput, marginBottom:8 }}/>
          <div style={{ display:"flex", gap:6 }}>
            <button onClick={saveAsset} style={{ flex:1, background:B.orange, border:"none", borderRadius:7, padding:"8px 0", fontSize:12, fontWeight:700, color:"white", cursor:"pointer", fontFamily:"inherit" }}>Save</button>
            <button onClick={()=>setPendingAsset(null)} style={{ ...eBtn, fontSize:11 }}>✕</button>
          </div>
        </div>
      )}

      {/* Recently used */}
      {recent.length>0 && (
        <div style={{ marginBottom:12 }}>
          <div style={{ fontSize:9, fontWeight:700, color:B.muted, textTransform:"uppercase", letterSpacing:"0.06em", marginBottom:6 }}>Recently Used</div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:5 }}>
            {recent.slice(0,6).map(a=>(
              <div key={a.id} title={a.name}
                draggable onDragStart={e=>{ e.dataTransfer.setData("assetId",a.id); e.dataTransfer.setData("assetUrl",a.dataUrl); }}
                onClick={()=>useAsset(a)}
                style={{ cursor:"pointer", borderRadius:7, overflow:"hidden", border:`1px solid ${B.border}`, position:"relative" }}>
                <img src={a.dataUrl} style={{ width:"100%", height:46, objectFit:"cover", display:"block" }}/>
                <div style={{ position:"absolute", bottom:0, left:0, right:0, background:"rgba(0,0,0,0.55)", fontSize:7, color:"white", padding:"1px 4px", overflow:"hidden", whiteSpace:"nowrap", textOverflow:"ellipsis" }}>{a.name}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* All assets grid */}
      {filtered.length===0 && assets.length===0 && (
        <div style={{ textAlign:"center", padding:"30px 0", color:B.muted, fontSize:12 }}>
          No assets yet.<br/>Upload images to build your library.
        </div>
      )}
      {filtered.length===0 && assets.length>0 && (
        <div style={{ textAlign:"center", padding:"20px 0", color:B.muted, fontSize:12 }}>No results for "{search}"</div>
      )}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:7 }}>
        {filtered.map(a=>(
          <div key={a.id}
            draggable onDragStart={e=>{ e.dataTransfer.setData("assetId",a.id); e.dataTransfer.setData("assetUrl",a.dataUrl); }}
            onClick={()=>useAsset(a)}
            style={{ cursor:"pointer", borderRadius:9, overflow:"hidden", border:`1px solid ${B.border}`, background:"rgba(255,255,255,0.03)", transition:"border-color 0.15s", position:"relative" }}
            onMouseEnter={e=>e.currentTarget.style.borderColor=B.orange}
            onMouseLeave={e=>e.currentTarget.style.borderColor=B.border}>
            <img src={a.dataUrl} style={{ width:"100%", height:62, objectFit:"cover", display:"block" }}/>
            <div style={{ padding:"5px 7px" }}>
              <div style={{ fontSize:10, fontWeight:600, color:"white", overflow:"hidden", whiteSpace:"nowrap", textOverflow:"ellipsis" }}>{a.name}</div>
              <div style={{ display:"flex", gap:3, flexWrap:"wrap", marginTop:2 }}>
                <span style={{ fontSize:8, color:B.orange, background:`${B.orange}18`, padding:"1px 5px", borderRadius:3 }}>{a.type}</span>
                {(a.tags||[]).slice(0,2).map(t=><span key={t} style={{ fontSize:8, color:"#6B7280", background:"rgba(255,255,255,0.05)", padding:"1px 5px", borderRadius:3 }}>{t}</span>)}
              </div>
            </div>
          </div>
        ))}
      </div>

      {assets.length>0 && (
        <div style={{ marginTop:14, fontSize:10, color:B.muted, textAlign:"center" }}>
          {assets.length} assets · Drag onto canvas or click to use
        </div>
      )}
    </div>
  );
}

