function checkBrandGuardrails(el) {
  const warnings = [];
  if (el.type === "text" && el.style?.fontSize < 7) warnings.push("Font too small — minimum 7pt");
  if (el.type === "text" && (el.content||"").length > 280) warnings.push("Too much text — over 280 chars");
  return warnings;
}
function checkSlideTextDensity(slide) {
  const textEls = (slide.elements||[]).filter(e=>e.type==="text"&&e.visible);
  const totalChars = textEls.reduce((n,e)=>n+(e.content||"").length, 0);
  if (totalChars > 400) return { level:"warn",  msg:`High text density (${totalChars} chars) — consider shorter copy` };
  if (totalChars > 600) return { level:"error", msg:`Very high text density (${totalChars} chars) — slide will look cluttered` };
  return null;
}

