/* ─── ARTICLE CONTENT FETCHER ───────────────────────────────────────── */
const ARTICLE_PROXIES = [
  url => `https://api.allorigins.win/get?url=${encodeURIComponent(url)}`,
  url => `https://corsproxy.io/?${encodeURIComponent(url)}`,
  url => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(url)}`,
];

function stripHtml(html) {
  // Remove scripts, styles, nav, footer, ads
  let text = html
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<nav[\s\S]*?<\/nav>/gi, " ")
    .replace(/<footer[\s\S]*?<\/footer>/gi, " ")
    .replace(/<header[\s\S]*?<\/header>/gi, " ")
    .replace(/<aside[\s\S]*?<\/aside>/gi, " ")
    .replace(/<!--[\s\S]*?-->/g, " ")
    .replace(/<[^>]+>/g, " ")           // strip all remaining tags
    .replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">")
    .replace(/&nbsp;/g," ").replace(/&quot;/g,'"')
    .replace(/\s{2,}/g, " ")            // collapse whitespace
    .trim();
  return text;
}

async function fetchArticleContent(url) {
  if (!url || !/^https?:\/\/.{10,}/.test(url)) {
    return { ok:false, text:"", error:"Invalid or missing URL" };
  }
  for (const makeProxy of ARTICLE_PROXIES) {
    try {
      const proxyUrl = makeProxy(url);
      const resp = await fetch(proxyUrl, { signal: AbortSignal.timeout(12000) });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const raw = await resp.text();
      // allorigins wraps in JSON
      let html = raw;
      try { const j = JSON.parse(raw); if (j.contents) html = j.contents; } catch(_){}
      if (!html.includes("<")) throw new Error("Response doesn't look like HTML");

      // Extract article body — try common article selectors via regex
      // Extract article content — try progressively wider selectors
      // Do NOT fall back to raw HTML (would include nav/ads/scripts)
      const articleMatch =
        html.match(/<article[^>]*>([\s\S]*?)<\/article>/i)?.[1] ||
        html.match(/class="[^"]*(?:article-body|post-content|entry-content|story-body|article__body|article-text|story-text|field--body)[^"]*"[^>]*>([\s\S]*?)<\/(?:div|section)>/i)?.[1] ||
        html.match(/<main[^>]*>([\s\S]*?)<\/main>/i)?.[1] ||
        // Last resort: extract <p> tags only (most article text lives in paragraphs)
        (html.match(/<p[^>]*>([\s\S]*?)<\/p>/gi)||[]).join(" ");

      const clean = stripHtml(articleMatch);
      // Trim to first 2500 chars of meaningful content
      const trimmed = clean.slice(0, 2500);
      if (trimmed.length < 100) throw new Error("Extracted text too short — likely paywalled or blocked");
      return { ok:true, text:trimmed, error:"" };
    } catch(e) {
      // Try next proxy
      if (ARTICLE_PROXIES.indexOf(makeProxy) === ARTICLE_PROXIES.length - 1) {
        return { ok:false, text:"", error: e.message };
      }
    }
  }
  return { ok:false, text:"", error:"All proxies failed" };
}

